package android.view; public class View {float sx=1,sy=1,x,y,px,py;boolean clip;ViewOutlineProvider provider;public int getWidth(){return 200;}public int getHeight(){return 300;}public int getMeasuredWidth(){return 200;}public int getMeasuredHeight(){return 300;}public void getLocationOnScreen(int[] l){l[0]=100;l[1]=200;}public float getScaleX(){return sx;}public float getScaleY(){return sy;}public void setScaleX(float v){sx=v;}public void setScaleY(float v){sy=v;}public float getTranslationX(){return x;}public float getTranslationY(){return y;}public void setTranslationX(float v){x=v;}public void setTranslationY(float v){y=v;}public float getPivotX(){return px;}public float getPivotY(){return py;}public void setPivotX(float v){px=v;}public void setPivotY(float v){py=v;}public ViewOutlineProvider getOutlineProvider(){return provider;}public void setOutlineProvider(ViewOutlineProvider p){provider=p;}public boolean getClipToOutline(){return clip;}public void setClipToOutline(boolean v){clip=v;}public android.graphics.Outline outline=new android.graphics.Outline();public void invalidateOutline(){if(provider!=null)provider.getOutline(this,outline);}public float visibleCenterX(){return 100+x+px+((outline.left+outline.right)/2-px)*sx;}public float visibleCenterY(){return 200+y+py+((outline.top+outline.bottom)/2-py)*sy;}}
